package io.scenariomesh.coordinator;import io.scenariomesh.core.Domain.*;import io.scenariomesh.workerruntime.DiscoveryMain;import java.nio.file.*;import java.time.*;import java.util.*;public final class ScenarioMeshRunner{public RunOutcome run(RunRequest request)throws Exception{RunId runId=RunId.create();Path dir=request.config().reportingDirectory().resolve("runs").resolve(runId.value());Files.createDirectories(dir);Instant started=Instant.now();DiscoveryMain.DiscoveryResult discovery=new DiscoveryProcess().discover(request,dir);List<ExecutionResult> results;try(WorkerPool workers=new WorkerPool(request,dir)){results=workers.execute(discovery.tasks());}Set<String> completed=new HashSet<>();for(ExecutionResult r:results)completed.add(r.scenarioId().value());List<ExecutionResult> complete=new ArrayList<>(results);for(var task:discovery.tasks())if(!completed.contains(task.id().value())){Instant now=Instant.now();complete.add(new ExecutionResult(task.id(),task.displayName(),ResultStatus.INFRASTRUCTURE_FAILURE,Duration.ZERO,new WorkerId("coordinator"),1,now,now,"No worker produced a terminal result for this task","MissingResult"));}return new RunOutcome(runId,discovery.adapters(),discovery.tasks(),complete,Duration.between(started,Instant.now()),dir);}}
